insert into phases (slug, short_label, name, window_label, goal, notes, sort_order) values
  ('p1', 'Phase 1', 'Foundation → Max Strength', 'Race minus ~21 weeks → minus 11 weeks', 'Re-groove the movements for two weeks, then get properly strong: heavy, low-rep, long rests. This is what improves running economy and late-race durability.', 'Weeks 1–2: moderate loads, 8s, learn the bar again. From week 3: work up to hard sets of 4–6 with 1–2 reps in reserve. Add ~2.5 kg to a lift whenever all sets are clean.', 1),
  ('p2', 'Phase 2', 'Race-Specific Strength', 'Race minus 11 weeks → minus 4 weeks', 'Heavy lifts drop to maintenance volume; the race pack comes out. Loaded step-ups, carries and single-leg stability turn gym strength into hill strength.', 'Pack step-ups mimic gates, stiles and steep hauls under load. Build pack weight 6 → 10 kg across the phase. Everything stays sub-maximal — running volume is peaking.', 2),
  ('p3', 'Phase 3', 'Taper & Maintain', 'Final ~26 days before race day', 'One short, crisp session a week keeps strength without stealing recovery. Nothing new, nothing heavy enough to cause soreness.', 'Last meaningful session ~10 days out. Final week: nothing beyond mobility and a few easy swings if you feel like moving.', 3),
  ('recovery', 'Recovery', 'Post-Race Recovery', '2 weeks after the race', 'You just raced. Walk, eat, sleep. Optional gentle upper session in week 2 if you are climbing the walls.', null, 4),
  ('p4', 'Phase 4', 'Rebuild & Physique Block', 'From ~2 weeks post-race', 'Running volume is low, so goal #2 takes the front seat: full-body training at moderate loads and reps (3×8–12), close to failure, where visible change happens. Reverts to the race structure ~14 weeks before your next A-race.', 'Same three days. Tue Lower, Thu Upper push-biased, Sat full-body pull-biased + core. Optional 4th short upper day if recovery is good.', 5)
insert into exercises (slug, name, category, video_url, rationale, cues, kit_note, space_note, ramp_note, swap_note, sort_order) values
  ('backsquat', 'Barbell back squat', 'Lower', 'https://www.youtube.com/watch?v=S0H0JxLAOAY', 'The engine of the whole plan — leg strength that survives mile 80.', '{"Brace before you unrack — big breath into the belt line","Sit down between your hips, chest proud","Drive the whole foot through the floor; knees track over toes"}'::text[], null, null, null, 'Goblet squat if the bar feels off, or box squat to a bench for depth control.', 1),
  ('gobletsquat', 'Goblet squat', 'Lower', 'https://www.youtube.com/watch?v=JO7D6GJ98wY', 'Warm-up groove and deload option; keeps the torso honest.', '{"Bell tight to the chest, elbows down","Ribs down — do not arch","Full depth, controlled up"}'::text[], null, null, null, null, 2),
  ('rdl', 'Romanian deadlift', 'Lower', 'https://www.youtube.com/watch?v=uhghy9pFIPY', 'Hamstrings and glutes under stretch — descent control for thousands of feet of downhill.', '{"Push the hips back, soft knees, bar shaved down the thighs","Stop where the hamstrings scream, not where the floor is","Flat back is non-negotiable"}'::text[], null, null, null, 'Dumbbell RDL when barbell setup is a faff.', 3),
  ('bss', 'Bulgarian split squat', 'Lower', 'https://www.youtube.com/watch?v=VPhhE6bBzZE', 'Single-leg strength with a big stability demand — the closest a gym gets to a rutted trail.', '{"Rear foot laces-down on the bench or the 16in box","Long stance, torso slightly forward loads the glute","Drive through the front heel; wobble is part of the work"}'::text[], '16in box gives a better rear-foot height than the bench for most people.', null, null, 'Reverse lunge if knees complain; hold the rack for balance while learning.', 4),
  ('stepup', 'Weighted step-up', 'Lower', 'https://www.youtube.com/watch?v=vOiHvzj5XhA', 'Concentric single-leg power — every stile, every step cut into a fell.', '{"Whole foot on the box, drive without pushing off the back leg","Start at 16in; 18in is the working height; 20in is roughly knee height for you and the hardest","Control the way down — that is half the exercise"}'::text[], 'Plyo box. 16in to learn and for higher reps, 18in as the default, 20in when you want it to bite.', null, null, 'Add the weighted vest before you add box height — height changes the joint angles, load does not.', 5),
  ('packstepup', 'Pack step-up (race pack)', 'Race', 'https://www.youtube.com/watch?v=qCW8V_rUpgM', 'THE mountain-race exercise. Your race pack, loaded, on a box — specificity you cannot buy.', '{"Wear the actual pack you will race with, straps dialled","Start 6 kg, build to race weight +2 kg by end of Phase 2","Steady rhythm, nose-breathing pace — this is durability, not a leg burner","18in box for volume, 20in when you want the big-step demand"}'::text[], 'Race pack + plyo box. Use the pack, not the vest, for this one — the point is rehearsing the exact load carriage you will race under, sway and hip belt included.', null, null, 'Vest version if the pack is packed for a race, or stair repeats with the pack on.', 6),
  ('slrdl', 'Single-leg RDL', 'Race', 'https://www.youtube.com/watch?v=CohgHMsoS2s', 'Balance + posterior chain + ankle proprioception in one move. Bog insurance.', '{"Kettlebell in the hand opposite the standing leg","Hips square, back leg reaches long","Grip the floor with your toes"}'::text[], null, null, null, 'Hold the rack with the free hand, or B-stance RDL.', 7),
  ('latlunge', 'Lateral lunge', 'Race', 'https://www.youtube.com/watch?v=qCA8E-dF8cI', 'Frontal-plane strength — the plane running never trains and camber, tussocks and sidesteps punish.', '{"Big sideways step, sit into that hip","Trailing leg straight, both heels down","Push back to standing through the bent leg"}'::text[], null, null, null, null, 8),
  ('kbswing', 'Kettlebell swing', 'Lower', 'https://www.youtube.com/watch?v=h-A7HiTNZ5c', 'Explosive hip power and posterior-chain conditioning in minutes.', '{"It is a hinge, not a squat","Hips throw the bell — arms are just rope","Snap tall at the top, glutes hard"}'::text[], null, null, null, null, 9),
  ('calfraise', 'Calf raise (slant board)', 'Ankle', 'https://www.youtube.com/watch?v=zGVzmZ9xOmE', 'Calf capacity is ankle armour and downhill braking. On the slant board the heel drops below the toes, so you get loaded range the floor cannot give you.', '{"3 s down into the stretch, pause, drive tall","Progress single-leg, then add a dumbbell, then the vest","Full range beats heavy half-reps"}'::text[], 'Slant board. Straight leg targets the gastrocnemius; the bent-knee version below is a separate exercise, not a variation.', null, null, 'Off a stair edge if the board is in use.', 10),
  ('soleusraise', 'Bent-knee soleus raise', 'Ankle', 'https://www.youtube.com/watch?v=pYs6drHFySs', 'Bend the knee and the gastrocnemius slackens, so the soleus takes the load. This matters more than most runners realise: the soleus carries the largest single share of force in late-stance running, it is the muscle that quietly fails on long descents, and straight-leg calf raises barely touch it.', '{"Knee bent to about 90°, heel dropped off the board edge","Slow — 2 s up, 3 s down","Load heavy; the soleus tolerates far more than you expect","15–20 reps, and it should burn"}'::text[], 'Slant board plus a dumbbell resting on the knee, or the vest on.', null, null, 'Seated on the bench with a dumbbell on the thigh.', 11),
  ('tib', 'Tibialis raise', 'Ankle', 'https://www.youtube.com/watch?v=KjaKJmWb_fI', 'The shin muscle that lifts your toes over 108 miles of tussock — and guards the ankle.', '{"Lean back on a wall, heels ~30 cm out","Lift both forefeet as high as they go","Slow lowers; burn is the point"}'::text[], 'Reverse the slant board (toes low, heels high) to add range once wall reps get easy.', null, null, null, 12),
  ('ankleiso', 'Banded ankle circuit', 'Ankle', 'https://www.youtube.com/watch?v=xfrncpP5ONQ', 'Eversion/inversion strength for your ankle history — small muscles, big insurance.', '{"Band around the forefoot: out, in, up — 15 each way","Slow and controlled, seated","Finish with 30 s single-leg balance, eyes closed if easy"}'::text[], null, null, null, 'During toe flare-ups this and isometric holds replace all impact work.', 13),
  ('farmer', 'Farmer / suitcase carry', 'Race', 'https://www.youtube.com/shorts/PV6Em-k0xYs', 'Grip, trunk, posture under load — carrying a heavy pack is literally the sport.', '{"Deadlift the bells up properly","Tall spine, ribs down, brisk short steps","Suitcase (one side) = brutal anti-lean core work"}'::text[], null, 'Needs ~10 m of clear floor. Kept here for when you train outdoors or have the room.', null, 'No room? Use the suitcase march, front-rack march or shuttle carry below. Marching keeps the stepping rhythm, which matters — see the note on each.', 14),
  ('suitcasemarch', 'Suitcase march (in place)', 'Race', 'https://www.youtube.com/watch?v=psMQmwlhiSs', 'The no-space replacement for the suitcase carry. One heavy bell at your side while you march on the spot — the load still tries to fold you sideways, and you still alternate legs, so the anti-lateral-flexion demand arrives in the same rhythm as walking under a pack.', '{"Deadlift the bell up; do not curl it into position","Nose, sternum and belt buckle stacked in a straight line","Knee to hip height, pause a beat, place it down softly","Do not let the free hand grab anything","Swap sides and match the reps exactly"}'::text[], null, 'One square metre. Nothing moves but you.', null, 'Progress by adding weight before adding time. 45 s a side is plenty; if it gets easy, get a heavier bell.', 15),
  ('frontrackmarch', 'Front-rack march', 'Race', 'https://www.youtube.com/watch?v=24Uj21nOPNw', 'Load sits on the front of the ribcage, so the trunk has to resist being pulled into extension while each leg lifts. This is the closest thing in the gym to a heavy chest-mounted pack on a steep climb.', '{"Clean the bells to the shoulders, elbows down and in","Ribs stacked over hips — no arching back","Slow march, full hip height, controlled foot placement","Breathe behind the brace; do not hold your breath"}'::text[], null, 'One square metre.', null, 'Single bell in the rack is harder than two — use it when the double gets easy.', 16),
  ('suitcasehold', 'Suitcase iso-hold', 'Race', 'https://www.youtube.com/watch?v=7G-m4LuXWu0', 'Static anti-lean work with a heavier bell than you could march with. Worth knowing that the EMG evidence has holds coming out slightly BELOW the walking versions for trunk activation — so this is the supplement, not the main course. Go heavier and longer to compensate.', '{"Stand tall, shoulders level, load hanging dead straight","Squeeze the opposite glute to stop the hip hiking","Grip is usually what fails first — that is fine, it is trainable","30–45 s a side, heavier than your march weight"}'::text[], null, 'Standing room only.', null, 'Barbell version in the rack lets you go much heavier than dumbbells allow.', 17),
  ('shuttlecarry', 'Shuttle carry (5 m turnaround)', 'Race', 'https://www.youtube.com/watch?v=V97zH30eO1g', 'If you can find five metres, this recovers the true walking carry. The turnarounds are a bonus — changing direction under load is exactly what stiles, gates and rocky steps demand.', '{"Short brisk steps, do not stroll","Slow and deliberate on the turn — that is where posture collapses","Set the bells down under control, never drop them"}'::text[], null, '5 m each way. Garage, hallway or driveway.', null, 'Falls back to the suitcase march if five metres is not available.', 18),
  ('stepdown', 'Eccentric box step-down', 'Race', 'https://www.youtube.com/watch?v=SZXOPRVP1Oc', 'The single most descent-specific thing you can do indoors. Running downhill is eccentric work — the quad lengthens under load on every footfall, and when it runs out of capacity you get the shaking, braking, quad-trashed feeling in the back half of a race. This trains exactly that contraction, slowly and under control.', '{"Stand on the box on one leg, other leg hanging free","Lower for a full 4–5 seconds — the slowness IS the exercise","Tap the heel lightly, do not take weight through it","Push back up through the standing leg normally","Knee tracks over the second toe; if it caves inward, drop to a lower box"}'::text[], 'Plyo box. Start 16in, progress to 18in, add the vest before you add height.', null, 'Sits on a Saturday, roughly 24 h before your long run — which is the front edge of when eccentric soreness peaks. That is survivable because the dose starts tiny and the repeated bout effect is strong: the first exposure does most of the damage, and by the third or fourth session the same load barely registers. So earn it. Weeks 1–2: one set of four, bodyweight, 16in box. Only add sets, height or vest once a Sunday has passed with no quad stiffness in the first 20 minutes. If a Sunday run ever feels quad-heavy early, drop back a step rather than pushing through.', 'If you would rather not gamble with the long run at all, move it to Tuesday — five days clear, at the cost of stacking quad load on heavy squat day.', 19),
  ('pullup', 'Pull-up', 'Upper', 'https://www.youtube.com/watch?v=6zyx46Vpato', 'The king of upper pulls — back width you can see, grip you can use.', '{"Dead hang start, shoulders down before you pull","Chest to bar direction, not chin-poke","Band assistance or slow negatives until reps come"}'::text[], 'The vest is the cleanest way to load these once you are past ~8 clean reps — far better than a dumbbell between the feet.', null, null, 'Band-assisted pull-up or slow 5 s negatives.', 20),
  ('ohp', 'Overhead press (DB or bar)', 'Upper', 'https://www.youtube.com/watch?v=Did01dFR3Lk', 'Shoulders that fill a t-shirt and press a pack overhead a fence.', '{"Glutes and core tight — no rib flare","Press to lockout, biceps by ears","Standing beats seated for trunk work"}'::text[], null, null, null, null, 21),
  ('dbbench', 'Dumbbell bench press', 'Upper', 'https://www.youtube.com/watch?v=pKZMNVbfUzQ', 'Chest and triceps with honest, even loading.', '{"Shoulder blades pinned to the bench","Slight arc: down-and-out, up-and-in","Feet planted, leg drive on"}'::text[], null, null, null, 'TRX or deficit push-ups when short on time.', 22),
  ('sarow', 'Single-arm dumbbell row', 'Upper', 'https://www.youtube.com/watch?v=pYcpY20QaE8', 'Thick mid-back, one side at a time — posture insurance for hours hunched into wind.', '{"Knee and hand on bench, flat back","Row to the hip, not the armpit","Squeeze, lower slow, no torso twist"}'::text[], null, null, null, null, 23),
  ('trxrow', 'TRX row', 'Upper', 'https://www.youtube.com/watch?v=fW_jdwZT804', 'Scales to any level by foot position; plank and pull at once.', '{"Body rigid as a board","Pull handles to lower ribs","Feet forward = harder"}'::text[], null, null, null, null, 24),
  ('pushacc', 'TRX push-up / dips off bench', 'Upper', 'https://www.youtube.com/watch?v=OlUqeytSoxE', 'Pressing volume without more dumbbell juggling.', '{"TRX push-up: handles low, body plank-rigid","Bench dips: shoulders down away from ears","Stop 2 reps shy of failure"}'::text[], null, null, null, null, 25),
  ('armfinisher', 'Curls + band pull-aparts', 'Upper', 'https://www.youtube.com/watch?v=zvmNxjcpvF8', 'Direct arm work (you said you want to see the fruits) plus rear-delt posture reps.', '{"Curl strict — no swing","Pull-aparts: squeeze shoulder blades, band to chest","Superset them, 2 rounds, done"}'::text[], null, null, null, null, 26),
  ('pallof', 'Pallof press', 'Core', 'https://www.youtube.com/watch?v=iBDXkpKDRy8', 'Anti-rotation — the core skill of running with a pack in a crosswind.', '{"Band anchored at the rack, stand side-on","Press out, resist the twist, pause 2 s","Half-kneeling version = harder than it looks"}'::text[], null, null, null, null, 27),
  ('deadbug', 'Dead bug', 'Core', 'https://www.youtube.com/watch?v=T1h8n4YMonY', 'Trunk control with a protected spine — perfect on tired days.', '{"Low back gently pressed to floor throughout","Opposite arm and leg reach long","Slow exhale each rep"}'::text[], null, null, null, null, 28),
  ('birddog', 'Bird dog', 'Core', 'https://www.youtube.com/watch?v=2aGunzN5YWA', 'Part of McGill’s Big 3 — spine stability with zero cost.', '{"Reach long, not high","Hips stay level — imagine a mug of tea on your back","Pause 3 s each rep"}'::text[], null, null, null, null, 29),
  ('sideplank', 'Side plank', 'Core', 'https://www.youtube.com/watch?v=iNbH7_edNI8', 'Lateral trunk endurance — camber and pack-lean resistance.', '{"Elbow under shoulder, body one line","Hips high","Progress: top leg raised or feet on bench"}'::text[], null, null, null, null, 30),
  ('hangknee', 'Hanging knee raise', 'Core', 'https://www.youtube.com/watch?v=l7OroezzX9k', 'Grip endurance + lower abs from your pull-up bar.', '{"Hang tall, no swing","Knees to chest with a posterior pelvic tilt","Lower slow"}'::text[], null, null, null, null, 31)
insert into sauna_types (slug, name, duration_label, temp_label, rationale, how_to, sort_order) values
  ('recov', 'Recovery sauna', '15–20 min', '70–80 °C', 'Circulation, stiffness, sleep and the simple fact that you enjoy it. No performance claim attached — this one is for feeling human.', '{"Go in warm, after training rather than before","15–20 min is plenty; this is not the adaptation session","Cool down gradually, then drink to your post-weight"}'::text[], 1),
  ('ha', 'Heat-acclimation session', '25–30 min', '80–100 °C', 'The dose that actually expands plasma volume. Straight after a run, while core temperature is already up — that is the protocol the research used, and it is far more time-efficient than heating from cold.', '{"Within ~10 min of finishing the run, before you cool off","Build to 25–30 min across the first week — do not open at full dose","Sit low for the first sessions if the top bench is too much","Weigh in and out. Every session."}'::text[], 2),
  ('post', 'Post-run top-up', '12–15 min', '70–80 °C', 'Short exposure that keeps some heat stimulus ticking over between blocks without adding meaningful fatigue.', '{"Straight off the run","Short and easy — leave before it becomes work","Skip it entirely on a heavy training week"}'::text[], 3),
  ('strength', 'Post-lift sauna', '15 min', '70–80 °C', 'Optional and low-stakes. Heat after lifting does not blunt strength adaptation the way cold-water immersion does, so if you like it, have it.', '{"After the session, never between sets","Keep it short on heavy lower days — you still have to run tomorrow"}'::text[], 4)
