insert into session_templates (slug, phase_slug, session_key, name, day_of_week, duration_label, brief, sort_order) values
  ('p1__lowerA', 'p1', 'lowerA', 'Lower A — Heavy Strength', 2, '~55 min', 'The money session. Warm up properly, lift heavy, leave crisp.', 1),
  ('p1__upper', 'p1', 'upper', 'Upper — Build', 4, '~50 min', 'Push/pull balance, moderate reps, 1–2 in reserve. Zero cost to the legs.', 2),
  ('p1__lowerB', 'p1', 'lowerB', 'Lower B + Core — Durability', 6, '~40 min', 'Sub-maximal by design. Quality movement; protect tomorrow’s long run.', 3),
  ('p2__lowerA', 'p2', 'lowerA', 'Lower A — Heavy Maintenance', 2, '~45 min', 'Strength stays, volume drops — running is peaking.', 1),
  ('p2__upper', 'p2', 'upper', 'Upper — Build', 4, '~45 min', 'Unchanged — this session never interferes.', 2),
  ('p2__race', 'p2', 'race', 'Race Builder — Pack & Carry', 6, '~45 min', 'The race in miniature: load, climb, descend, carry, stabilise.', 3),
  ('p3__maintain', 'p3', 'maintain', 'Taper — Maintain', 2, '~30 min', 'One crisp session a week. Nothing that causes soreness. Last real session ~10 days out.', 1),
  ('recovery__easyupper', 'recovery', 'easyupper', 'Optional — Easy Upper', 4, '~30 min', 'Week 2 post-race only, and only if you genuinely want to move.', 1),
  ('p4__p4lower', 'p4', 'p4lower', 'Lower — Strength & Shape', 2, '~55 min', 'Hypertrophy dial up: 8–12 reps, close to failure, full range.', 1),
  ('p4__p4push', 'p4', 'p4push', 'Upper — Push Bias', 4, '~55 min', 'Press-heavy day. Chase clean reps, add small weight often.', 2),
  ('p4__p4pull', 'p4', 'p4pull', 'Full Body — Pull Bias + Core', 6, '~55 min', 'Back, hinge and trunk. Optional 4th short upper day mid-week if recovery is good.', 3)
