  ('p1', 'sa_thu', 4, 'recov', true, 'Easy day, easy heat.', 2),
  ('p1', 'sa_sun', 0, 'post', false, 'After the long run — rehydrate first, then heat.', 3),
  ('p2', 'sa_tue', 2, 'post', true, 'Short only. Running volume is peaking.', 1),
  ('p2', 'sa_thu', 4, 'recov', true, null, 2),
  ('p2', 'sa_sat', 6, 'strength', true, 'After the Race Builder session.', 3),
  ('p2', 'sa_sun', 0, 'post', false, 'Long-run recovery slot.', 4),
  ('p3', 'sa_recov', 4, 'recov', true, 'Taper: comfort only. The heat block below is what matters now.', 1),
  ('p3', 'sa_sun', 0, 'recov', true, 'Keep it short and pleasant.', 2),
  ('recovery', 'sa_r1', 3, 'recov', true, 'Purely for feeling better. No dose target.', 1),
  ('recovery', 'sa_r2', 0, 'recov', true, null, 2),
  ('p4', 'sa_tue', 2, 'strength', true, 'After the lower session.', 1),
  ('p4', 'sa_thu', 4, 'recov', true, null, 2),
  ('p4', 'sa_sat', 6, 'strength', true, null, 3),
  ('p4', 'sa_sun', 0, 'post', false, 'The one to keep if you only keep one.', 4)
