insert into recipes (slug, name, meal_type, cuisine_code, diet_tag, heat_level, time_minutes, cost_band, serves, description, spice_note, tip, sort_order) values
  ('gochu_tofu', 'Gochujang crispy tofu bowls', 'dinner', 'Asian', 'veg', 2, 30, '£', 2, 'Cornflour-crisped tofu in a sticky gochujang-soy-honey glaze over rice, charred broccoli, sesame.', 'Extra gochugaru or chilli crisp on your bowl only.', 'Batch the glaze ×3 — it keeps two weeks and upgrades everything.', 1),
  ('miso_salmon', 'Miso-ginger salmon traybake', 'dinner', 'Asian', 'fish', 0, 25, '££', 2, 'Salmon fillets in miso-ginger-maple glaze roasted with pak choi and sweet potato wedges.', 'Shichimi togarashi or chilli oil over your fillet.', 'Salmon is amber-list: 2–3 fish meals a week total is the ceiling.', 2),
  ('green_curry', 'Thai green curry, tofu & green beans', 'dinner', 'Asian', 'veg', 3, 30, '£', 2, 'Green curry with tofu, green beans, bamboo shoots and Thai basil over jasmine rice — base kept at 🌶🌶.', 'Sliced bird’s-eye chillies and extra paste fried in oil, spooned over your bowl.', 'Check the paste is shrimp-paste-free (vegetarian ones are) — keeps it firmly green-list.', 3),
  ('yakitori', 'Yakitori-style chicken skewers', 'dinner', 'Asian', 'chicken', 1, 35, '££', 2, 'Chicken thigh skewers glazed with soy-mirin-ginger tare, grilled spring onions, rice, quick-pickled radish.', 'Ichimi/chilli flakes on yours.', 'One of your two weekly chicken slots.', 4),
  ('dandan', 'Dan dan-ish noodles (soy mince)', 'dinner', 'Asian', 'veg', 3, 25, '£', 2, 'Sichuan-style sesame-chilli sauce, crispy soy mince, wheat noodles, wilted greens, crushed peanuts. Sauce built to 🌶🌶.', 'Double chilli oil + extra Sichuan pepper ground over your bowl — proper má là.', 'Full-flavour flagship. Chilli oil jar = pantry MVP.', 5),
  ('lemongrass_chicken', 'Vietnamese lemongrass chicken', 'dinner', 'Asian', 'chicken', 2, 30, '££', 2, 'Caramelised lemongrass-chilli chicken with rice, pickled carrot, herbs and nuoc-cham-style dressing (light on fish sauce).', 'Fresh red chilli in your dressing.', 'Fish sauce stays at teaspoons — flavour without the purine load.', 6),
  ('kimchi_rice', 'Kimchi fried rice + fried egg', 'dinner', 'Asian', 'veg', 2, 15, '£', 2, 'Day-old rice, kimchi and its juice, spring onion, sesame, topped with a crispy fried egg each.', 'Gochugaru in the pan-half that becomes your portion.', 'The 15-minute emergency dinner. Cook extra rice earlier in the week on purpose.', 7),
  ('saltpepper_tofu', 'Salt & pepper crispy tofu', 'dinner', 'Asian', 'veg', 2, 30, '£', 2, 'Takeaway-style crispy tofu with fried garlic, chilli and spring onion over rice and charred tenderstem.', 'Keep half the fried chillies aside and pile them on yours.', null, 8),
  ('teriyaki_fish', 'Teriyaki white fish, sesame greens', 'dinner', 'Asian', 'fish', 0, 20, '££', 2, 'Cod or haddock in quick teriyaki, steamed rice, sesame-garlic spring greens.', 'Chilli oil over your fillet.', 'White fish is the gentlest fish choice for urate.', 9),
  ('mapo', 'Mapo tofu (mushroom-free)', 'dinner', 'Asian', 'veg', 3, 25, '£', 2, 'Tofu in a fiery-but-shared doubanjiang and Sichuan pepper sauce with soy mince, over rice. Base at 🌶🌶.', 'Extra doubanjiang fried in chilli oil, spooned over yours — restores full Sichuan violence.', 'Classically has mushroom or pork — this version needs neither and loses nothing.', 10),
  ('singapore', 'Singapore noodles, egg & veg', 'dinner', 'Asian', 'veg', 2, 20, '£', 2, 'Curried rice vermicelli with egg ribbons, peppers, beansprouts and spring onion.', 'Fresh red chilli + hot curry powder pinch on your half.', null, 11),
  ('massaman', 'Massaman-style sweet potato & peanut curry', 'dinner', 'Asian', 'veg', 1, 40, '£', 2, 'Mild-warm coconut curry with sweet potato, peanuts, tofu and rice — the batch-cook king.', 'Crispy chilli oil on top of yours.', 'Doubles brilliantly — freeze two portions, win a future Tuesday.', 12),
  ('bibimbap', 'Bibimbap bowls', 'dinner', 'Asian', 'veg', 2, 35, '£', 2, 'Rice bowls with seasoned spinach, carrot, courgette, marinated tofu, fried egg and gochujang sauce.', 'Your sauce = gochujang + gochugaru; hers straight gochujang.', null, 13),
  ('soba', 'Miso soba with edamame & greens', 'dinner', 'Asian', 'veg', 0, 15, '£', 2, 'Chilled or warm soba in miso-sesame dressing with edamame, shredded greens and nori.', 'Rayu (Japanese chilli oil) over yours.', 'The night-before-long-run dinner: carby, quick, gentle.', 14),
  ('sichuan_aub', 'Sichuan-style aubergine, rice', 'dinner', 'Asian', 'veg', 3, 30, '£', 2, 'Silky roasted aubergine in garlic-chilli-black-vinegar sauce, rice, sesame. Sauce at 🌶🌶.', 'Dried chillies fried crisp in oil, crumbled over your plate.', null, 15),
  ('seabass', 'Ginger & spring onion steamed sea bass', 'dinner', 'Asian', 'fish', 1, 20, '££', 2, 'Cantonese-style: steamed sea bass, hot oil over ginger and spring onion, soy, rice and greens.', 'Fresh sliced chilli under the hot oil on your fillet.', null, 16),
  ('paneer_tikka', 'Paneer tikka traybake, flatbreads', 'dinner', 'Asian', 'veg', 2, 35, '£', 2, 'Yogurt-spiced paneer and peppers roasted hot, with flatbreads, mint yogurt and tomato-onion salad (no cucumber).', 'Kashmiri chilli + green chilli in your half of the marinade.', 'Dairy protein = actively gout-protective. Full-flavour and cheap.', 17),
  ('chana', 'Chana masala + rice', 'dinner', 'Asian', 'veg', 2, 30, '£', 2, 'Deeply spiced chickpea curry — tomato, ginger, garam masala — with rice or flatbreads.', 'Tadka of green chillies and chilli powder in hot oil, poured over your bowl.', 'Cheapest meal in the bank. Legume purines are green-list — enjoy freely.', 18),
  ('padthai', 'Egg & tofu pad thai-style noodles', 'dinner', 'Asian', 'veg', 2, 25, '£', 2, 'Rice noodles, tamarind-soy-lime sauce, tofu, egg, beansprouts, peanuts, plenty of lime.', 'Dried chilli flakes fried with your portion.', 'Traditional fish sauce swapped for soy + tamarind — you will not miss it.', 19),
  ('laksa', 'Tofu & veg laksa', 'dinner', 'Asian', 'veg', 3, 30, '£', 2, 'Rich coconut-chilli noodle soup with fried tofu, green beans and beansprouts. Broth built to 🌶🌶.', 'Sambal or extra laksa paste fried in oil, stirred into your bowl only.', null, 20),
  ('chipotle_chilli', 'Chipotle black bean chilli', 'dinner', 'Mexican', 'veg', 2, 35, '£', 2, 'Deep smoky chilli — chipotle, cumin, dark chocolate — with black beans, peppers and sweet potato. Lime, yogurt and coriander on top.', null, 'The batch-cook champion of the whole bank — makes 4, freezes perfectly. Chilli heat lives in the chipotle, so scale it to taste.', 21),
  ('bean_tacos', 'Black bean & sweet potato tacos, chipotle slaw', 'dinner', 'Mexican', 'veg', 2, 30, '£', 2, 'Cumin-roasted sweet potato and smoky beans in warm tortillas, with crunchy chipotle-lime cabbage slaw and feta.', null, 'Feta as accent, not blanket — keeps it light while adding the salty hit.', 22),
  ('baja_fish', 'Baja-style fish tacos', 'dinner', 'Mexican', 'fish', 1, 30, '££', 2, 'Spiced pan-fried white fish, quick-pickled onion, shredded cabbage, lime crema and hot sauce at the table.', null, 'Frozen white fish is cheaper and works fine here — one of your 2–3 weekly fish slots.', 23),
  ('huevos', 'Huevos rancheros', 'dinner', 'Mexican', 'veg', 2, 20, '£', 2, 'Eggs poached in a chilli-tomato sauce over crisped tortillas with black beans, feta and avocado.', null, 'Eggs are green-list and cheap. Brilliant post-long-run dinner.', 24),
  ('burrito_bowl', 'Charred corn & bean burrito bowls', 'dinner', 'Mexican', 'veg', 1, 25, '£', 2, 'Coriander-lime rice, black beans, blistered corn, pico de gallo, avocado and a smoky yogurt drizzle.', null, 'Assembles from pantry in 25 minutes. The lunchbox version of itself the next day.', 25),
  ('tinga', 'Chicken tinga tostadas', 'dinner', 'Mexican', 'chicken', 2, 35, '££', 2, 'Shredded chicken braised in smoky chipotle-tomato sauce, piled on crisp tortillas with slaw, feta and lime.', null, 'One of your two weekly chicken slots.', 26),
  ('enchiladas', 'Salsa verde bean enchiladas', 'dinner', 'Mexican', 'veg', 2, 40, '£', 2, 'Tortillas rolled around black beans and peppers, baked under tangy tomatillo-style green salsa and a little melted cheese.', null, 'Comfort-food category, big flavour, cheese kept to a modest layer.', 27),
  ('aji_verde', 'Peruvian aji verde chicken & potatoes', 'dinner', 'Mexican', 'chicken', 2, 45, '££', 2, 'Cumin-roasted chicken and crushed potatoes with a punchy green sauce of chilli, coriander, lime and yogurt.', null, 'The aji verde keeps a week and turns leftovers into a different meal.', 28),
  ('shakshuka', 'Shakshuka with feta', 'dinner', 'MidEast', 'veg', 2, 25, '£', 2, 'Eggs baked in a spiced pepper-tomato sauce with cumin, paprika and harissa, crumbled feta, flatbread to mop.', null, '20-minute dinner, all green-list. Add a tin of chickpeas to make it bigger on hungry days.', 29),
  ('harissa_cauli', 'Harissa cauliflower & chickpea traybake', 'dinner', 'MidEast', 'veg', 2, 40, '£', 2, 'Whole roasted cauliflower florets and chickpeas in harissa and cumin, lemon-tahini yogurt, pomegranate and herbs.', null, 'One tray, huge flavour, dirt cheap. Cauliflower is high-purine on paper and completely fine in practice.', 30),
  ('tagine', 'Chickpea, squash & apricot tagine', 'dinner', 'MidEast', 'veg', 1, 40, '£', 2, 'Warm-spiced stew — cinnamon, ginger, ras el hanout — with butternut, chickpeas and dried apricots over couscous. Harissa at the table.', null, 'Traditionally has olives — left out entirely, and the apricots carry it. Heat added at the table.', 31),
  ('mujadara', 'Mujadara — lentils, rice & crispy onions', 'dinner', 'MidEast', 'veg', 0, 45, '£', 2, 'Cumin-scented lentils and rice under a mountain of deeply caramelised onions, with herby yogurt and tomato salad.', null, 'The cheapest dinner in the file and one of the best. No heat as written — chilli oil at the table if you want it.', 32),
  ('berbere', 'Berbere lentil stew', 'dinner', 'MidEast', 'veg', 3, 35, '£', 2, 'Ethiopian-spiced red lentils, fiery and fragrant, with collard-style greens and flatbread or rice.', null, 'Properly hot as written — the berbere does it. Halve the spice for a milder pan.', 33),
  ('falafel_patties', 'Baked falafel patties, tahini sauce', 'dinner', 'MidEast', 'veg', 1, 35, '£', 2, 'Herby chickpea patties baked crisp, with lemon-tahini sauce, tomato-red onion salad and warm flatbreads.', null, 'Salad is tomato-and-onion rather than the usual cucumber-heavy version.', 34),
  ('zaatar_salmon', 'Za’atar salmon with bulgur & herbs', 'dinner', 'MidEast', 'fish', 0, 25, '££', 2, 'Salmon crusted in za’atar over lemony bulgur wheat loaded with parsley, mint, spring onion and pomegranate.', null, 'Counts toward your 2–3 weekly fish meals.', 35),
  ('lentil_soup', 'Turkish red lentil soup, chilli butter', 'dinner', 'MidEast', 'veg', 1, 30, '£', 2, 'Silky red lentil and carrot soup finished with paprika-chilli oil, lemon and torn flatbread.', null, 'Pre-long-run dinner or the night you cannot face cooking. Freezes well.', 36),
  ('halloumi_bake', 'Harissa halloumi & chickpea traybake', 'dinner', 'MidEast', 'veg', 2, 35, '££', 2, 'Halloumi, chickpeas, peppers and red onion roasted hard in harissa and honey, with lemon yogurt and couscous.', null, 'Halloumi is the flavour accent; the chickpeas carry the protein.', 37),
  ('kofte_lentil', 'Spiced lentil köfte with yogurt & sumac', 'dinner', 'MidEast', 'veg', 2, 35, '£', 2, 'Red lentil and bulgur köfte, pan-crisped, with garlicky yogurt, sumac onions and a tomato-herb salad.', null, 'Comfort food that happens to be almost entirely legumes and grains.', 38),
  ('l_sesame_tofu', 'Sesame-soy tofu rice bowl', 'lunch', 'Asian', 'veg', 1, 8, '£', 1, 'Ready-marinated tofu, pouch rice, edamame and carrot ribbons under a soy-sesame drizzle. Boxed cold, eaten cold or warm.', 'Chilli crisp spooned over just before you eat.', 'Frozen edamame defrosts in the box by lunchtime — no pan, no kettle.', 39),
  ('l_kimchi_egg', 'Kimchi, egg & nori rice box', 'lunch', 'Asian', 'veg', 2, 7, '£', 1, 'Cold rice, kimchi, two boiled eggs, gochujang mayo and torn nori. Four minutes if the eggs are already done.', 'Extra gochugaru through the mayo.', 'Boil six eggs on Sunday and this becomes the fastest box in the file.', 40),
  ('l_vermicelli', 'Vermicelli, herb & pickled carrot pot', 'lunch', 'Asian', 'veg', 1, 10, '£', 1, 'Kettle-soaked rice noodles, smoked tofu, shredded lettuce, masses of mint and coriander, nuoc-cham-style dressing in a separate pot.', 'Sliced red chilli in the dressing jar.', 'Vermicelli only needs boiling water and three minutes — no hob involved.', 41),
  ('l_onigirazu', 'Tuna-mayo & avocado nori wrap', 'lunch', 'Asian', 'fish', 0, 8, '££', 1, 'Onigirazu — a nori-wrapped rice sandwich of tuna mayo, avocado and carrot. Cuts in half and holds together in a bag.', 'Wasabi or chilli oil stirred through the mayo.', 'Tuna is amber-list — keep this to once a week alongside your two fish dinners.', 42),
  ('l_crunch_slaw', 'Peanut-lime crunch slaw, smoked tofu', 'lunch', 'Asian', 'veg', 2, 10, '£', 1, 'Cabbage, carrot and pepper shredded fine, smoked tofu battons, peanut-lime-ginger dressing, crushed peanuts on top.', 'Chilli oil or sriracha whisked into the dressing.', 'Shred a big tub of slaw on Sunday and dress the portion, not the tub — it stays crisp all week.', 43),
  ('l_bean_wrap', 'Black bean, feta & avocado wrap', 'lunch', 'Mexican', 'veg', 1, 7, '£', 1, 'Crushed black beans with chipotle and lime, avocado, feta, tomato and red onion rolled tight.', 'Hot sauce straight into the bean mash.', 'Crush half the beans — that is what stops the wrap unravelling in your bag.', 44),
  ('l_chipotle_chick', 'Chipotle chickpea & sweetcorn bowl', 'lunch', 'Mexican', 'veg', 2, 8, '£', 1, 'Chickpeas, sweetcorn, pepper and red onion over pouch rice, chipotle-yogurt drizzle, lime and coriander.', 'Extra chipotle paste on your side of the bowl.', 'Chickpeas and yogurt in one bowl: plant protein plus the dairy that actively lowers urate.', 45),
  ('l_salmon_taco', 'Hot-smoked salmon & lime slaw tacos', 'lunch', 'Mexican', 'fish', 1, 8, '££', 1, 'Flaked hot-smoked salmon, sharp lime cabbage slaw, chipotle yogurt and pickled red onion in soft tortillas.', 'Hot sauce over the flaked salmon.', 'Amber-list — count it as one of your 2–3 weekly fish servings, not an extra.', 46),
  ('l_mezze', 'Hummus & za’atar chickpea plate', 'lunch', 'MidEast', 'veg', 0, 6, '£', 1, 'Hummus spread thick, chickpeas tumbled over with za’atar and lemon, tomato-onion-parsley salad, flatbread to scoop.', 'Harissa or chilli flakes swirled through the hummus.', 'The six-minute lunch. Buy hummus in the big tub — it works out half the price.', 47),
  ('l_bulgur_jar', 'Herby bulgur, feta & pomegranate jar', 'lunch', 'MidEast', 'veg', 0, 10, '£', 1, 'Tabbouleh-leaning jar: kettle-soaked fine bulgur, a forest of parsley and mint, tomato, spring onion, feta, pomegranate, sumac and lemon.', 'Chilli flakes and extra sumac on top.', 'Pour boiling water on the bulgur before your shower; it is done before you are.', 48),
  ('l_lentil_beet', 'Lentil, beetroot & feta box', 'lunch', 'MidEast', 'veg', 0, 7, '£', 1, 'Ready-cooked puy lentils, vac-packed beetroot, spinach, feta and walnuts under a lemon-tahini dressing.', 'Harissa stirred into the tahini dressing.', 'Plant purines, dairy protein, deep-pigment veg — about as urate-friendly as a lunch gets.', 49),
  ('l_falafel_wrap', 'Falafel, tahini & pickled cabbage wrap', 'lunch', 'MidEast', 'veg', 1, 8, '£', 1, 'Shop-bought falafel crumbled into a flatbread with quick vinegar cabbage, tomato, tahini sauce and harissa.', 'Extra harissa striped down the wrap.', 'Ten minutes of cabbage in vinegar does the job of a proper pickle.', 50),
  ('l_shawarma_wrap', 'Shawarma-spiced chicken & yogurt wrap', 'lunch', 'MidEast', 'chicken', 1, 8, '££', 1, 'Cold cooked chicken tossed in baharat and lemon, garlicky yogurt, tomato and onion, rolled in a flatbread.', 'Harissa or chilli sauce through the yogurt.', 'Uses one of your two weekly chicken slots — cheapest built from Sunday leftovers.', 51),
  ('sw_egg_cress', 'Egg mayo & cress sandwich', 'lunch', 'Simple', 'veg', 0, 5, '£', 1, 'Proper egg mayo — coarsely crushed, mustard-sharp, plenty of black pepper — with cress on thick bread.', 'Sriracha or chilli flakes through the mayo.', 'Boil a batch of eggs on Sunday and three of these lunches build themselves.', 52),
  ('sw_hummus_pepper', 'Hummus, roast pepper & feta sandwich', 'lunch', 'Simple', 'veg', 1, 5, '£', 1, 'Jarred roasted peppers, thick hummus, crumbled feta and spinach in seeded bread. No chopping worth the name.', 'Harissa or chilli flakes over the hummus.', 'A jar of roasted peppers is the single best-value sandwich upgrade in the shop.', 53),
  ('sw_cheese_pickle', 'Cheddar, pickle & apple sandwich', 'lunch', 'Simple', 'veg', 0, 4, '£', 1, 'Mature cheddar, sweet pickle or chutney, thin apple slices for crunch. The whole thing takes four minutes.', 'Add sliced pickled jalapeño.', 'Cheese is a gout ally, not a risk — dairy protein actively lowers urate.', 54),
  ('sw_tuna_crunch', 'Tuna crunch & sweetcorn wrap', 'lunch', 'Simple', 'fish', 0, 5, '£', 1, 'Tuna mixed with sweetcorn, spring onion and half-yogurt mayo, rolled in a tortilla with lettuce.', 'Sriracha stirred into the mix.', 'Amber-list — one tinned-fish lunch a week, not three.', 55),
  ('sw_chickpea_smash', 'Smashed chickpea & lemon sandwich', 'lunch', 'Simple', 'veg', 0, 6, '£', 1, 'Chickpeas crushed with yogurt, lemon and mustard into something between houmous and egg mayo. Cheap and genuinely filling.', 'Chilli flakes and a spoon of harissa.', 'About 45p a sandwich and 15 g of protein. Hard to beat.', 56),
  ('sa_chopped_feta', 'Chopped chickpea, feta & sweetcorn salad', 'lunch', 'Simple', 'veg', 0, 7, '£', 1, 'Everything diced to the same size, dressed with lemon and mustard. Travels better than leaves and does not wilt.', 'Chilli flakes over the top.', null, 57),
  ('sa_potato_egg', 'New potato, egg & green bean salad', 'lunch', 'Simple', 'veg', 0, 7, '£', 1, 'Cold new potatoes, halved boiled eggs, green beans and a mustard-yogurt dressing. Built entirely from things already cooked.', 'Chilli flakes and extra mustard.', 'Boil extra potatoes with any dinner — this is what they are for.', 58),
  ('sa_apple_cheddar', 'Apple, walnut & cheddar spinach salad', 'lunch', 'Simple', 'veg', 0, 5, '£', 1, 'Spinach, sharp apple, cubed cheddar and walnuts under a lemon-mustard dressing. Five ingredients, five minutes.', 'Chilli flakes or a spoon of chutney in the dressing.', 'Add a slice of bread if it is a long-run day — on its own it is light on carbs.', 59),
  ('sa_butterbean', 'Butter bean, roasted pepper & feta salad', 'lunch', 'Simple', 'veg', 1, 5, '£', 1, 'Tinned butter beans, jarred peppers, feta, red onion and lemon. Almost entirely store-cupboard.', 'Chilli flakes and a spoon of harissa.', 'Butter beans are the creamiest tinned pulse and criminally underused.', 60),
  ('to_avo_egg', 'Smashed avocado & egg on sourdough', 'lunch', 'Simple', 'veg', 1, 5, '£', 1, 'Avocado crushed with lemon and salt, halved boiled eggs, chilli flakes and plenty of pepper.', 'More chilli flakes, or chilli oil over the top.', null, 61),
  ('to_beans_herb', 'Herby white beans on toast', 'lunch', 'Simple', 'veg', 1, 6, '£', 1, 'Cannellini beans warmed with garlic, lemon and parsley, piled on toast. Ready before the toaster pops twice.', 'Chilli flakes fried into the oil first.', 'Microwave the beans for 60 seconds if you would rather not touch a pan.', 62),
  ('to_pb_banana', 'Peanut butter, banana & cinnamon toast', 'lunch', 'Simple', 'veg', 0, 3, '£', 1, 'The three-minute post-long-run lunch: thick peanut butter, sliced banana, cinnamon, a scatter of seeds.', 'Not really a chilli dish. Leave this one alone.', 'Carbs plus protein within the hour after a long run — pair with skyr for the full 30 g.', 63),
  ('bf_cherry_oats', 'Cherry, chia & skyr overnight oats', 'breakfast', 'Simple', 'veg', 0, 5, '£', 1, 'The 6 am run-day default: oats soaked overnight in skyr and milk with frozen cherries and chia. Zero effort at the point of eating.', 'Not a chilli dish — a scrape of ginger or cardamom instead.', 'Dairy protein plus cherries in one bowl — the single most urate-protective breakfast you can eat. Make three jars at once.', 64),
  ('bf_skyr_bowl', 'Skyr, berry & granola bowl', 'breakfast', 'Simple', 'veg', 0, 3, '£', 1, 'Skyr, frozen berries thawed overnight, granola and seeds. Three minutes, 25 g of protein, no cooking.', 'Leave it be.', 'Skip the honey drizzle — fructose raises urate, and the fruit is doing that job already.', 65),
  ('bf_pb_porridge', 'Peanut butter & banana porridge', 'breakfast', 'Simple', 'veg', 0, 8, '£', 1, 'Milk-cooked porridge with peanut butter stirred through and banana on top. The pre-long-run breakfast — carbs plus enough fat to keep you going.', 'A pinch of salt does more for this than chilli would.', 'Eat 90 minutes before a long run. Milk rather than water adds 12 g of protective dairy protein.', 66),
  ('bf_eggs_avo', 'Scrambled eggs, avocado & toast', 'breakfast', 'Simple', 'veg', 1, 10, '£', 1, 'Soft scrambled eggs, crushed avocado, seeded toast, chilli flakes. The rest-day breakfast that holds until lunch.', 'Chilli flakes or chilli oil over the eggs.', 'Low and slow off the heat is the whole technique — eggs finish cooking in the pan after you stop.', 67),
  ('bf_recovery_smoothie', 'Cherry, banana & skyr recovery smoothie', 'breakfast', 'Simple', 'veg', 0, 4, '£', 1, 'Blitzed straight after a long run: frozen cherries, banana, skyr, milk and oats. Around 30 g of protein and fast carbs in one glass.', 'A knob of ginger blitzed in is the only heat this wants.', 'Drink within the hour after hard sessions. Tart cherry has the best evidence of any food for both urate and muscle soreness.', 68),
  ('bf_miso_egg_rice', 'Miso, egg & nori rice bowl', 'breakfast', 'Asian', 'veg', 1, 8, '£', 1, 'Japanese-style savoury breakfast: hot rice, a soft egg, miso stirred into the grains, nori and spring onion.', 'Chilli oil or shichimi over the egg.', 'The savoury option for mornings when you cannot face another sweet bowl.', 69),
  ('bf_bagel_egg', 'Egg, cream cheese & tomato bagel', 'breakfast', 'Simple', 'veg', 0, 7, '£', 1, 'Toasted bagel, cream cheese, sliced boiled egg and tomato. The big-carb morning — race day, long-run day, or any day you woke up hungry.', 'Chilli flakes or hot sauce on the egg.', 'Practise this one before race day — bagels sit well in a stomach that has to run afterwards.', 70),
  ('bk_cherry_flapjack', 'Oat, cherry & seed flapjacks', 'batch', 'Simple', 'veg', 0, 40, '£', 12, 'Dense oat flapjacks with dried cherries and seeds. Run fuel, mid-afternoon fuel, or a pocket bar for hill reps.', 'A pinch of chilli in the mix is a real thing, but start with ginger instead.', 'Cherries are the one food with real evidence behind it for urate — worth building into a weekly bake.', 71),
  ('bk_banana_loaf', 'Banana, walnut & yogurt loaf', 'batch', 'Simple', 'veg', 0, 65, '£', 10, 'Yogurt keeps it damp for four days. Barely sweet, heavy with banana and walnuts — closer to a fuel loaf than a cake.', 'Ginger and cardamom rather than heat.', 'Freezes in slices — take one out at 6 am and it has thawed by the time you finish a long run.', 72),
  ('bk_frittata_muffins', 'Feta & spinach frittata muffins', 'batch', 'Simple', 'veg', 1, 35, '£', 12, 'Baked egg muffins with spinach, feta, spring onion and roasted pepper. Two of these plus fruit is a real lunch.', 'Chilli flakes through the egg mix.', 'About 9 g of protein each and they keep four days in the fridge. The best lunchbox item in this file.', 73),
  ('bk_cheese_carrot_muffins', 'Cheese, carrot & seed savoury muffins', 'batch', 'Simple', 'veg', 0, 40, '£', 12, 'Wholemeal savoury muffins with grated carrot, cheddar and seeds. Bread substitute, soup companion, desk snack.', 'Chilli flakes or a spoon of harissa in the batter.', 'No yeast extract anywhere near these — that stays firmly on the red list.', 74),
  ('bk_energy_balls', 'Date, cocoa & peanut energy balls', 'batch', 'Simple', 'veg', 0, 15, '£', 16, 'No baking at all: blitz, roll, chill. Dense, chocolatey, and about 90 calories of very portable carbohydrate each.', 'A pinch of chilli with the cocoa actually works here.', 'Fructose caution: dates are concentrated sugar, so treat these as run fuel rather than all-day grazing.', 75),
  ('bk_race_bars', 'Rice, sesame & maple race bars', 'batch', 'Simple', 'veg', 0, 20, '£', 10, 'Sticky pressed rice bars in the Japanese onigiri-meets-flapjack tradition. Easy to chew cold, and survives a pocket.', 'A shake of shichimi if you want a savoury version.', 'Gut-training food. Start practising these on long runs in Phase 2, not in January.', 76),
  ('bk_soda_bread', 'Yogurt & seed soda bread', 'batch', 'Simple', 'veg', 0, 55, '£', 10, 'No kneading, no proving, no yeast. Mix, shape, bake — a loaf inside an hour that carries every sandwich above.', 'Not applicable, but chilli-cheese variations exist.', 'Cheaper than shop sourdough by a distance, and you know exactly what is in it.', 77)
