insert into recipe_steps (recipe_slug, step_no, instruction) values
  ('gochu_tofu', 1, 'Press the tofu 10 min between kitchen paper under something heavy, then cube. Start the rice.'),
  ('gochu_tofu', 2, 'Toss the tofu in cornflour with a good pinch of salt until every face is dusted.'),
  ('gochu_tofu', 3, 'Fry in a hot, generously oiled pan, turning only when each side has properly crusted — 8–10 min total.'),
  ('gochu_tofu', 4, 'Mix gochujang, soy, rice vinegar and a splash of water into a glaze.'),
  ('gochu_tofu', 5, 'Char the broccoli in a dry hot pan with a splash of water and a lid, 4 min.'),
  ('gochu_tofu', 6, 'Kill the heat, pour the glaze over the tofu and toss to coat. Serve on rice, scattered with spring onion and sesame.'),
  ('miso_salmon', 1, 'Heat oven to 200°C. Toss sweet potato wedges in oil and salt, roast 20 min.'),
  ('miso_salmon', 2, 'Whisk miso, grated ginger, maple and soy into a paste.'),
  ('miso_salmon', 3, 'Push the wedges aside, add the salmon, spoon the glaze thickly over each fillet.'),
  ('miso_salmon', 4, 'Roast 10–12 min until the salmon flakes and the glaze has caught at the edges.'),
  ('miso_salmon', 5, 'Add pak choi (halved) for the last 4 min. Finish with lime.'),
  ('green_curry', 1, 'Start the rice. Cube and pat the tofu dry.'),
  ('green_curry', 2, 'Fry the curry paste in a little oil for 2 min until it smells fierce — this step is the difference between good and flat.'),
  ('green_curry', 3, 'Pour in the coconut milk, bring to a gentle simmer.'),
  ('green_curry', 4, 'Add tofu, green beans and bamboo shoots. Simmer 8 min.'),
  ('green_curry', 5, 'Off the heat, stir through torn Thai basil and a big squeeze of lime. Taste for salt.'),
  ('yakitori', 1, 'Simmer soy, mirin, a splash of water, grated ginger and a pinch of sugar for 5 min until slightly syrupy. This is your tare.'),
  ('yakitori', 2, 'Cut chicken into 3 cm pieces, thread onto skewers with spring onion between.'),
  ('yakitori', 3, 'Grill or griddle hot, 3–4 min a side, brushing with tare each turn.'),
  ('yakitori', 4, 'Slice radishes thin and steep in rice vinegar with a pinch of salt while the chicken cooks.'),
  ('yakitori', 5, 'Serve over rice with the remaining tare spooned over.'),
  ('dandan', 1, 'Fry the mince hard in a dry-ish hot pan until genuinely crispy — 8 min, resist stirring too often.'),
  ('dandan', 2, 'Splash in 1 tbsp soy at the end and let it caramelise. Set aside.'),
  ('dandan', 3, 'Whisk tahini, chilli oil, remaining soy, crushed garlic and 4–5 tbsp hot water into a loose sauce. Add Sichuan pepper if using.'),
  ('dandan', 4, 'Boil the noodles; wilt the greens in the water for the last minute.'),
  ('dandan', 5, 'Pour sauce into warm bowls, pile noodles on top, crown with crispy mince and crushed peanuts. Toss at the table.'),
  ('lemongrass_chicken', 1, 'Bash the lemongrass, chop finely with chilli and garlic. Toss with the chicken, fish sauce and brown sugar. Marinate while the rice cooks (15 min is plenty).'),
  ('lemongrass_chicken', 2, 'Shred the carrot, steep in lime juice with a pinch of sugar and salt.'),
  ('lemongrass_chicken', 3, 'Fry the chicken in a hot pan, undisturbed at first, until deeply caramelised — 10–12 min.'),
  ('lemongrass_chicken', 4, 'Mix a dressing of lime juice, a little fish sauce, sugar and water.'),
  ('lemongrass_chicken', 5, 'Serve on rice with pickled carrot, mint, coriander and the dressing poured over.'),
  ('kimchi_rice', 1, 'Chop the kimchi roughly, keeping the juice.'),
  ('kimchi_rice', 2, 'Fry the whites of the spring onion in sesame oil, add kimchi and cook 3 min until it loses its rawness.'),
  ('kimchi_rice', 3, 'Add cold rice, breaking up clumps, and fry hard 4–5 min so it catches. Add kimchi juice, soy and peas.'),
  ('kimchi_rice', 4, 'Fry the eggs separately in hot oil until the edges are lacy and crisp.'),
  ('kimchi_rice', 5, 'Serve rice topped with the egg, remaining spring onion and sesame.'),
  ('saltpepper_tofu', 1, 'Cube and dry the tofu thoroughly. Toss in cornflour, five spice, plenty of salt and white or black pepper.'),
  ('saltpepper_tofu', 2, 'Shallow-fry in 1 cm of hot oil, turning, until deeply golden — 8 min. Drain on paper.'),
  ('saltpepper_tofu', 3, 'In a second pan char the tenderstem with a splash of water and a lid.'),
  ('saltpepper_tofu', 4, 'Fry sliced garlic, chilli and spring onion in a little oil for 60 seconds until fragrant but not browned.'),
  ('saltpepper_tofu', 5, 'Toss the tofu through the aromatics off the heat. Serve immediately with rice.'),
  ('teriyaki_fish', 1, 'Simmer soy, mirin, grated ginger and a pinch of sugar for 4 min until it coats a spoon.'),
  ('teriyaki_fish', 2, 'Pat the fish dry, season, and fry skin-side down in a hot pan for 4 min.'),
  ('teriyaki_fish', 3, 'Flip, add the sauce, and baste for 2–3 min until the fish flakes.'),
  ('teriyaki_fish', 4, 'Wilt the greens in a separate pan with garlic and sesame.'),
  ('teriyaki_fish', 5, 'Serve over rice with the pan sauce poured over.'),
  ('mapo', 1, 'Cube the tofu and warm it gently in salted water — this stops it collapsing later. Drain.'),
  ('mapo', 2, 'Fry the mince with garlic and ginger until dry and browned.'),
  ('mapo', 3, 'Add doubanjiang and Sichuan pepper, fry 2 min until the oil turns red.'),
  ('mapo', 4, 'Add 200 ml water, simmer 5 min. Slide in the tofu and simmer 3 min without stirring hard.'),
  ('mapo', 5, 'Thicken with cornflour slaked in cold water. Scatter spring onion. Serve on rice.'),
  ('singapore', 1, 'Soak the vermicelli in just-boiled water 3 min, drain, rinse cold.'),
  ('singapore', 2, 'Beat the eggs, cook flat in an oiled wok, roll and slice into ribbons. Set aside.'),
  ('singapore', 3, 'Stir-fry pepper and spring onion 2 min, add curry powder and fry 30 seconds.'),
  ('singapore', 4, 'Add noodles, peas, soy and a splash of water. Toss hard over high heat.'),
  ('singapore', 5, 'Fold through beansprouts and egg ribbons at the last moment so they stay crisp.'),
  ('massaman', 1, 'Start the rice. Peel and chunk the sweet potatoes; slice the onion.'),
  ('massaman', 2, 'Fry the curry paste in oil 2 min, add onion, cook 3 min.'),
  ('massaman', 3, 'Add coconut milk, 150 ml water, sweet potato and half the peanuts. Simmer 20–25 min until tender.'),
  ('massaman', 4, 'Add the tofu for the last 5 min so it warms without breaking.'),
  ('massaman', 5, 'Finish with lime and the remaining peanuts, roughly crushed.'),
  ('bibimbap', 1, 'Cook the rice. Julienne the carrot and courgette.'),
  ('bibimbap', 2, 'Cook each vegetable separately and briefly — spinach wilted with garlic, carrot 2 min, courgette 3 min — seasoning each with sesame oil and salt.'),
  ('bibimbap', 3, 'Fry the marinated tofu until golden on all sides.'),
  ('bibimbap', 4, 'Mix gochujang with a little sesame oil, water and a pinch of sugar into a spoonable sauce.'),
  ('bibimbap', 5, 'Arrange everything in sections over rice, top with a fried egg, and mix furiously at the table.'),
  ('soba', 1, 'Whisk miso, tahini, rice vinegar and 3 tbsp warm water into a pourable dressing.'),
  ('soba', 2, 'Boil the soba 4–5 min. Add the edamame for the final 2 min and the greens for the final minute.'),
  ('soba', 3, 'Drain and rinse under cold water if serving cool; leave warm if not.'),
  ('soba', 4, 'Toss everything through the dressing.'),
  ('soba', 5, 'Top with nori or sesame.'),
  ('sichuan_aub', 1, 'Heat oven to 220°C. Cut aubergines into thick batons, toss in oil and salt, roast 25 min until collapsing and browned.'),
  ('sichuan_aub', 2, 'Start the rice.'),
  ('sichuan_aub', 3, 'Fry garlic and ginger 1 min, add doubanjiang or chilli oil and fry 1 min more.'),
  ('sichuan_aub', 4, 'Add soy, black vinegar, a pinch of sugar and 4 tbsp water; simmer 2 min.'),
  ('sichuan_aub', 5, 'Fold the roasted aubergine through the sauce. Scatter spring onion and sesame. Serve on rice.'),
  ('seabass', 1, 'Set up a steamer (a plate over a pan of simmering water with a lid works).'),
  ('seabass', 2, 'Julienne half the ginger and half the spring onions; lay the rest under the fish.'),
  ('seabass', 3, 'Steam the sea bass 7–8 min until opaque and flaking.'),
  ('seabass', 4, 'Pour off any watery liquid, top with the julienned ginger and spring onion, and drizzle over soy.'),
  ('seabass', 5, 'Heat 2 tbsp oil until smoking and pour it over the aromatics — it should hiss. Serve with rice and steamed pak choi.'),
  ('paneer_tikka', 1, 'Heat oven to 220°C. Cube the paneer, chunk the peppers and onion.'),
  ('paneer_tikka', 2, 'Mix yogurt with the spice paste and salt; coat the paneer and vegetables and leave 10 min.'),
  ('paneer_tikka', 3, 'Spread on a tray and roast 20 min, turning once, until charred at the edges.'),
  ('paneer_tikka', 4, 'Chop tomatoes and red onion, dress with lemon and salt.'),
  ('paneer_tikka', 5, 'Stir mint into the remaining yogurt. Warm the flatbreads and build.'),
  ('chana', 1, 'Fry the diced onion in oil 8 min until properly soft and golden — do not rush this.'),
  ('chana', 2, 'Add garlic, ginger and the ground spices, fry 2 min until fragrant.'),
  ('chana', 3, 'Add tomatoes, cook down 5 min until the oil separates at the edges.'),
  ('chana', 4, 'Add drained chickpeas and 150 ml water. Simmer 15 min, crushing some chickpeas against the pan to thicken.'),
  ('chana', 5, 'Finish with coriander and a squeeze of lemon. Serve with rice or flatbread.'),
  ('padthai', 1, 'Soak the noodles in warm water until pliable but not soft. Drain.'),
  ('padthai', 2, 'Whisk tamarind, soy, a pinch of sugar and lime juice into a sauce.'),
  ('padthai', 3, 'Fry the cubed tofu until golden, push aside, scramble the eggs in the same pan.'),
  ('padthai', 4, 'Add noodles and sauce, toss hard over high heat 2 min until they take on colour.'),
  ('padthai', 5, 'Fold through beansprouts off the heat. Serve with peanuts, spring onion and lime wedges.'),
  ('laksa', 1, 'Fry the paste in oil 2–3 min until it darkens and smells fragrant.'),
  ('laksa', 2, 'Add coconut milk and 300 ml water, simmer 5 min.'),
  ('laksa', 3, 'Add fried tofu and green beans, simmer 5 min.'),
  ('laksa', 4, 'Cook the noodles separately and divide between bowls.'),
  ('laksa', 5, 'Ladle the soup over, top with beansprouts, coriander and lime.'),
  ('chipotle_chilli', 1, 'Fry diced onion, pepper and sweet potato in oil 8 min.'),
  ('chipotle_chilli', 2, 'Add garlic, cumin, smoked paprika and chipotle paste; fry 2 min.'),
  ('chipotle_chilli', 3, 'Add tomatoes, drained beans and 200 ml water. Simmer 20 min, uncovered, until thick.'),
  ('chipotle_chilli', 4, 'Stir in the dark chocolate — it deepens everything without tasting sweet.'),
  ('chipotle_chilli', 5, 'Taste hard for salt and acid; finish with lime. Serve with rice, yogurt and coriander.'),
  ('bean_tacos', 1, 'Heat oven to 220°C. Cube sweet potato, toss with cumin, oil and salt, roast 25 min.'),
  ('bean_tacos', 2, 'Shred the cabbage, dress with lime, a little yogurt, chipotle and salt. Leave to soften.'),
  ('bean_tacos', 3, 'Warm the beans in a pan with a splash of water and a pinch of cumin, crushing some to thicken.'),
  ('bean_tacos', 4, 'Char the tortillas directly over a gas flame or in a dry pan.'),
  ('bean_tacos', 5, 'Build: beans, sweet potato, slaw, crumbled feta, coriander, more lime.'),
  ('baja_fish', 1, 'Slice the red onion thin and steep in lime juice with salt — 15 min makes it pink and sharp.'),
  ('baja_fish', 2, 'Mix yogurt with lime zest, juice and salt for the crema.'),
  ('baja_fish', 3, 'Pat the fish dry, dust with paprika, cumin and salt, fry in a hot oiled pan 3 min a side. Break into chunks.'),
  ('baja_fish', 4, 'Warm the tortillas.'),
  ('baja_fish', 5, 'Build with shredded cabbage, fish, pickled onion, crema and coriander. Hot sauce at the table.'),
  ('huevos', 1, 'Fry the diced onion 5 min, add garlic and chopped chilli, 1 min.'),
  ('huevos', 2, 'Add tomatoes, a pinch of sugar and salt; simmer 8 min until thick.'),
  ('huevos', 3, 'Stir in the drained beans and warm through.'),
  ('huevos', 4, 'Make four wells, crack in the eggs, cover and cook 5–6 min until whites set and yolks stay loose.'),
  ('huevos', 5, 'Crisp the tortillas in a dry pan. Serve the eggs over them with feta, avocado and coriander.'),
  ('burrito_bowl', 1, 'Cook the rice; when done, fork through lime juice, zest and chopped coriander.'),
  ('burrito_bowl', 2, 'Char the sweetcorn in a dry hot pan until blistered and popping, 5 min.'),
  ('burrito_bowl', 3, 'Warm the beans with cumin and a splash of water.'),
  ('burrito_bowl', 4, 'Dice tomato and red onion, dress with lime and salt for a quick pico.'),
  ('burrito_bowl', 5, 'Thin the yogurt with lime and smoked paprika. Assemble bowls and drizzle.'),
  ('tinga', 1, 'Poach the chicken thighs in salted water 15 min, then shred with two forks. Keep the liquid.'),
  ('tinga', 2, 'Fry sliced onion 8 min until soft, add garlic and oregano.'),
  ('tinga', 3, 'Add tomatoes and chipotle, simmer 10 min, then blend smooth if you want it silky.'),
  ('tinga', 4, 'Return the chicken with a ladle of poaching liquid; simmer 10 min until glossy.'),
  ('tinga', 5, 'Crisp the tortillas in the oven or a dry pan. Top with tinga, shredded cabbage, feta and lime.'),
  ('enchiladas', 1, 'Heat oven to 200°C. Fry sliced peppers and onion 8 min.'),
  ('enchiladas', 2, 'Stir in the drained beans and a few spoons of green salsa; season well.'),
  ('enchiladas', 3, 'Roll the filling into the tortillas and pack seam-down into a baking dish.'),
  ('enchiladas', 4, 'Pour the remaining salsa over, scatter cheese and sliced jalapeños.'),
  ('enchiladas', 5, 'Bake 20 min until bubbling. Serve with yogurt and coriander.'),
  ('aji_verde', 1, 'Heat oven to 200°C. Toss chicken with cumin, salt and oil; roast 35 min.'),
  ('aji_verde', 2, 'Boil the potatoes 15 min, drain, crush lightly and roast alongside the chicken for the last 20 min.'),
  ('aji_verde', 3, 'Blend chillies, coriander, garlic, yogurt, lime and salt into a vivid green sauce. Loosen with water.'),
  ('aji_verde', 4, 'Taste the sauce for heat and salt — it should be punchy enough to make you blink.'),
  ('aji_verde', 5, 'Serve the chicken and potatoes with the sauce poured over generously.'),
  ('shakshuka', 1, 'Fry sliced onion and peppers in oil 10 min until soft and sweet.'),
  ('shakshuka', 2, 'Add garlic, cumin, paprika and harissa; fry 2 min.'),
  ('shakshuka', 3, 'Add tomatoes and a pinch of sugar, simmer 10 min until thick enough to hold a well.'),
  ('shakshuka', 4, 'Make four wells, crack in the eggs, cover and cook 6 min until the whites set.'),
  ('shakshuka', 5, 'Scatter feta and parsley. Serve straight from the pan with flatbread.'),
  ('harissa_cauli', 1, 'Heat oven to 220°C. Break the cauliflower into florets, drain the chickpeas and pat dry.'),
  ('harissa_cauli', 2, 'Toss both with harissa, cumin, oil and salt. Spread on a tray without crowding.'),
  ('harissa_cauli', 3, 'Roast 30 min, turning once, until the cauliflower is charred at the tips.'),
  ('harissa_cauli', 4, 'Whisk tahini, yogurt, lemon juice and water into a pourable sauce; season.'),
  ('harissa_cauli', 5, 'Pile onto a platter, spoon over the sauce, scatter pomegranate and herbs. Warm flatbreads.'),
  ('tagine', 1, 'Fry diced onion in oil 8 min, add garlic, ginger and ras el hanout, fry 2 min.'),
  ('tagine', 2, 'Add chunked squash, tomatoes, chickpeas, apricots and 300 ml water.'),
  ('tagine', 3, 'Simmer covered 25 min until the squash is tender but holding.'),
  ('tagine', 4, 'Meanwhile pour boiling water over the couscous, cover, and leave 8 min. Fork through.'),
  ('tagine', 5, 'Taste for salt and sweetness. Scatter almonds and coriander. Harissa on the table.'),
  ('mujadara', 1, 'Slice the onions thin. Fry in a generous amount of oil over medium heat 20–25 min until deep brown and crisp. Patience here is the entire dish.'),
  ('mujadara', 2, 'Lift out half the onions to drain; leave the rest in the pan.'),
  ('mujadara', 3, 'Simmer the lentils in salted water 15 min until nearly tender, drain.'),
  ('mujadara', 4, 'Add rice, lentils, cumin and cinnamon to the pan with 400 ml water. Cover, cook 15 min, rest 10 min off the heat.'),
  ('mujadara', 5, 'Top with the crisp onions. Serve with lemony yogurt and a tomato-parsley salad.'),
  ('berbere', 1, 'Fry diced onions in oil 10 min until soft and browning.'),
  ('berbere', 2, 'Add garlic, ginger and berbere; fry 2 min — it will smell intense.'),
  ('berbere', 3, 'Add lentils, tomatoes and 700 ml water. Simmer 20 min, stirring, until collapsed and thick.'),
  ('berbere', 4, 'Stir the shredded greens through for the last 5 min.'),
  ('berbere', 5, 'Season hard — lentils absorb more salt than you expect. Serve with flatbread or rice.'),
  ('falafel_patties', 1, 'Heat oven to 220°C. Drain and thoroughly dry the chickpeas.'),
  ('falafel_patties', 2, 'Blitz chickpeas, herbs, garlic, spices and salt to a coarse paste — stop before it becomes hummus.'),
  ('falafel_patties', 3, 'Shape into 8 patties, brush with oil, bake 25 min turning once, until crisp outside.'),
  ('falafel_patties', 4, 'Whisk tahini with lemon juice, water and salt until it loosens into a smooth sauce.'),
  ('falafel_patties', 5, 'Chop tomato and red onion with lemon and chilli flakes. Serve in warm flatbreads.'),
  ('zaatar_salmon', 1, 'Rinse the bulgur, cover with boiling water, and leave 15 min until tender. Drain well.'),
  ('zaatar_salmon', 2, 'Press za’atar firmly onto the salmon fillets, season.'),
  ('zaatar_salmon', 3, 'Fry skin-side down in a hot pan 4 min, flip, 2–3 min more.'),
  ('zaatar_salmon', 4, 'Toss the bulgur with masses of chopped parsley, mint, spring onion, lemon juice and oil.'),
  ('zaatar_salmon', 5, 'Serve the salmon on the bulgur with pomegranate and a spoon of yogurt.'),
  ('lentil_soup', 1, 'Fry diced onion and carrot in oil 8 min.'),
  ('lentil_soup', 2, 'Add cumin, paprika and lentils, stir 1 min.'),
  ('lentil_soup', 3, 'Add 900 ml water or stock, simmer 20 min until the lentils have collapsed.'),
  ('lentil_soup', 4, 'Blend smooth (or half-smooth if you like texture). Loosen with water as needed.'),
  ('lentil_soup', 5, 'Melt butter or oil with chilli flakes and paprika, drizzle over each bowl. Lemon and mint to finish.'),
  ('halloumi_bake', 1, 'Heat oven to 220°C. Chunk the halloumi, peppers and red onion; drain the chickpeas.'),
  ('halloumi_bake', 2, 'Toss everything with harissa, honey, oil and salt.'),
  ('halloumi_bake', 3, 'Spread on a tray and roast 25 min until the halloumi is bronzed and the onions catching.'),
  ('halloumi_bake', 4, 'Soak the couscous in boiling water 8 min, covered. Fork through with lemon zest.'),
  ('halloumi_bake', 5, 'Mix yogurt with lemon juice and salt. Serve the tray over couscous with the yogurt and torn mint.'),
  ('kofte_lentil', 1, 'Simmer the red lentils in 500 ml water 15 min until collapsed and thick.'),
  ('kofte_lentil', 2, 'Stir in the fine bulgur off the heat, cover, and leave 20 min to swell.'),
  ('kofte_lentil', 3, 'Fry one diced onion until soft, add tomato purée, cumin and paprika, cook 3 min. Stir through the lentil mix with plenty of salt.'),
  ('kofte_lentil', 4, 'Shape into small ovals with wet hands. Crisp in an oiled pan a few minutes a side.'),
  ('kofte_lentil', 5, 'Slice the second onion thin, toss with sumac and lemon. Serve with garlicky yogurt and a tomato-parsley salad.'),
  ('l_sesame_tofu', 1, 'Peel the carrot into ribbons with the peeler; slice the tofu into fingers.'),
  ('l_sesame_tofu', 2, 'Tip the frozen edamame straight into the box — it will be perfectly defrosted by lunchtime.'),
  ('l_sesame_tofu', 3, 'Layer rice, tofu, edamame and carrot. Scatter spring onion and sesame.'),
  ('l_sesame_tofu', 4, 'Shake soy and sesame oil in a small pot and carry it separately; pour over just before eating.'),
  ('l_kimchi_egg', 1, 'Boil the eggs 7 minutes in advance (do six at once on a Sunday) and peel.'),
  ('l_kimchi_egg', 2, 'Stir mayonnaise with gochujang until smooth.'),
  ('l_kimchi_egg', 3, 'Pack rice in the base, kimchi and its juice at one end, halved eggs on top.'),
  ('l_kimchi_egg', 4, 'Tear the nori over, add spring onion and sesame, and carry the gochujang mayo in a pot.'),
  ('l_vermicelli', 1, 'Cover the vermicelli with boiling water, leave 3 minutes, drain and rinse cold. Toss with a drop of oil so it does not clump.'),
  ('l_vermicelli', 2, 'Shred the carrot and lettuce; slice the tofu.'),
  ('l_vermicelli', 3, 'Shake lime juice, fish sauce, sugar and 2 tbsp water together for the dressing.'),
  ('l_vermicelli', 4, 'Layer noodles, tofu, carrot, lettuce and herbs. Peanuts and dressing travel separately.'),
  ('l_onigirazu', 1, 'Lay a nori sheet on cling film, shiny side down, in a diamond.'),
  ('l_onigirazu', 2, 'Mix the drained tuna with mayo and soy. Slice the avocado; peel the carrot into ribbons.'),
  ('l_onigirazu', 3, 'Press half the rice into a square in the middle, then tuna, avocado and carrot, then the remaining rice.'),
  ('l_onigirazu', 4, 'Fold all four corners of the nori in over the top, wrap tightly in the film and leave 5 minutes before cutting in half.'),
  ('l_crunch_slaw', 1, 'Shred cabbage, carrot and pepper as fine as you can be bothered to — finer is genuinely better here.'),
  ('l_crunch_slaw', 2, 'Whisk peanut butter, lime juice, soy, grated ginger and 2–3 tbsp water into a pourable dressing.'),
  ('l_crunch_slaw', 3, 'Pack the vegetables and tofu batons in the box, dressing in a separate pot.'),
  ('l_crunch_slaw', 4, 'Toss at your desk and top with crushed peanuts and coriander so they stay crunchy.'),
  ('l_bean_wrap', 1, 'Drain the beans, crush half of them roughly with a fork and mix with chipotle, lime juice and salt.'),
  ('l_bean_wrap', 2, 'Spread the bean mash down the middle of the wrap, leaving a clear border.'),
  ('l_bean_wrap', 3, 'Add sliced avocado, crumbled feta, halved tomatoes, thin red onion and coriander.'),
  ('l_bean_wrap', 4, 'Roll tight, fold the base, and wrap in foil — it holds all morning.'),
  ('l_chipotle_chick', 1, 'Drain the chickpeas and sweetcorn; dice the pepper and onion.'),
  ('l_chipotle_chick', 2, 'Stir yogurt with chipotle, lime juice, smoked paprika and salt into a drizzle.'),
  ('l_chipotle_chick', 3, 'Pack rice at the base, then chickpeas, corn, pepper and onion in sections.'),
  ('l_chipotle_chick', 4, 'Carry the chipotle yogurt and coriander separately; eat cold or 60 seconds in a microwave.'),
  ('l_salmon_taco', 1, 'Shred the cabbage and toss with lime juice and salt; leave 10 minutes to soften.'),
  ('l_salmon_taco', 2, 'Steep thin red onion slices in the rest of the lime juice.'),
  ('l_salmon_taco', 3, 'Mix yogurt with chipotle and a pinch of salt.'),
  ('l_salmon_taco', 4, 'Flake the salmon. Carry tortillas, slaw, salmon and crema in separate compartments and build at the table.'),
  ('l_mezze', 1, 'Spread the hummus across the base of a shallow box, hollowing the middle.'),
  ('l_mezze', 2, 'Drain the chickpeas, dry them, and toss with za’atar, lemon juice and salt.'),
  ('l_mezze', 3, 'Pile the chickpeas into the hollow.'),
  ('l_mezze', 4, 'Chop tomatoes, onion and parsley with lemon and salt, add alongside, and pack the flatbread separately so it stays dry.'),
  ('l_bulgur_jar', 1, 'Cover the bulgur with boiling water by 1 cm, cover and leave 15 minutes, then fork through and cool.'),
  ('l_bulgur_jar', 2, 'Chop parsley, mint, tomatoes and spring onion finely — the herbs should outweigh the grain.'),
  ('l_bulgur_jar', 3, 'Toss everything with lemon juice, sumac and salt.'),
  ('l_bulgur_jar', 4, 'Layer into a jar with feta and pomegranate on top; shake before eating.'),
  ('l_lentil_beet', 1, 'Whisk tahini with lemon juice, a pinch of salt and 2–3 tbsp water until it loosens and turns pale.'),
  ('l_lentil_beet', 2, 'Dice the beetroot; drain the lentil pouch if it needs it.'),
  ('l_lentil_beet', 3, 'Pack spinach at the base, lentils and beetroot over it, feta and walnuts on top.'),
  ('l_lentil_beet', 4, 'Dressing in a separate pot — beetroot bleeds into everything if you dress it early.'),
  ('l_falafel_wrap', 1, 'Shred the cabbage, toss with vinegar and salt, leave 10 minutes.'),
  ('l_falafel_wrap', 2, 'Loosen the tahini with lemon juice and water until it pours.'),
  ('l_falafel_wrap', 3, 'Warm the flatbread for 20 seconds if you have a microwave, otherwise use it as is.'),
  ('l_falafel_wrap', 4, 'Crumble the falafel down the middle, add cabbage, tomato, tahini, harissa and parsley, then roll and foil-wrap.'),
  ('l_shawarma_wrap', 1, 'Slice or shred the cold chicken and toss with baharat, lemon juice and salt.'),
  ('l_shawarma_wrap', 2, 'Grate the garlic into the yogurt with a pinch of salt.'),
  ('l_shawarma_wrap', 3, 'Slice the tomato and onion thin.'),
  ('l_shawarma_wrap', 4, 'Spread the yogurt on the flatbread, add chicken, salad and parsley, roll tightly and wrap in foil.'),
  ('sw_egg_cress', 1, 'Peel the boiled eggs and crush roughly with a fork — lumps are the point.'),
  ('sw_egg_cress', 2, 'Fold in mayonnaise, mustard, plenty of salt and far more black pepper than feels sensible.'),
  ('sw_egg_cress', 3, 'Pile onto one slice, cover thickly with cress, close and press down.'),
  ('sw_egg_cress', 4, 'Cut on the diagonal. Wrap in foil if it is travelling.'),
  ('sw_hummus_pepper', 1, 'Spread hummus thickly on both slices — it doubles as the butter.'),
  ('sw_hummus_pepper', 2, 'Drain the peppers, pat dry, and lay them flat.'),
  ('sw_hummus_pepper', 3, 'Crumble the feta over, squeeze lemon on top, add spinach.'),
  ('sw_hummus_pepper', 4, 'Close, press firmly and cut in half.'),
  ('sw_cheese_pickle', 1, 'Slice the cheddar thick rather than grating it.'),
  ('sw_cheese_pickle', 2, 'Spread pickle on one slice, right to the edges.'),
  ('sw_cheese_pickle', 3, 'Slice the apple thinly and layer it over the cheese with the spinach.'),
  ('sw_cheese_pickle', 4, 'Close, press, cut. Foil-wrap if boxed.'),
  ('sw_tuna_crunch', 1, 'Drain the tuna and sweetcorn thoroughly — wet filling means a soggy wrap.'),
  ('sw_tuna_crunch', 2, 'Mix with yogurt, mayonnaise, sliced spring onion, salt and pepper.'),
  ('sw_tuna_crunch', 3, 'Spoon down the middle of the tortilla, leaving a clear border.'),
  ('sw_tuna_crunch', 4, 'Add shredded lettuce, fold the base up, roll tight and wrap in foil.'),
  ('sw_chickpea_smash', 1, 'Drain the chickpeas and crush with a fork until half are broken and half survive whole.'),
  ('sw_chickpea_smash', 2, 'Mix in yogurt, mustard, lemon juice, salt and pepper.'),
  ('sw_chickpea_smash', 3, 'Fold through finely diced red onion and chopped parsley.'),
  ('sw_chickpea_smash', 4, 'Pile onto bread, close, and press hard so it holds together.'),
  ('sa_chopped_feta', 1, 'Dice pepper, tomatoes and onion to roughly the same size — this is what makes a chopped salad work.'),
  ('sa_chopped_feta', 2, 'Drain the chickpeas and sweetcorn well.'),
  ('sa_chopped_feta', 3, 'Whisk lemon juice, mustard, oil, salt and pepper in the base of the box.'),
  ('sa_chopped_feta', 4, 'Pile everything on top, feta and parsley last. Shake when you sit down to eat.'),
  ('sa_potato_egg', 1, 'Halve the cold potatoes; halve the boiled eggs.'),
  ('sa_potato_egg', 2, 'Blanch the green beans in the kettle if raw, or use them straight from a cooked batch.'),
  ('sa_potato_egg', 3, 'Whisk yogurt, mustard, lemon juice, salt and pepper into a dressing.'),
  ('sa_potato_egg', 4, 'Layer potatoes, beans and eggs, scatter spring onion and parsley, and carry the dressing separately.'),
  ('sa_apple_cheddar', 1, 'Whisk lemon juice, mustard, a little oil, salt and pepper in the base of the box.'),
  ('sa_apple_cheddar', 2, 'Cube the cheddar and slice the apple thickly.'),
  ('sa_apple_cheddar', 3, 'Add spinach, apple, cheddar and walnuts on top of the dressing without mixing.'),
  ('sa_apple_cheddar', 4, 'Shake to dress at the last moment so the spinach stays crisp.'),
  ('sa_butterbean', 1, 'Drain and rinse the butter beans; drain the peppers and slice them into strips.'),
  ('sa_butterbean', 2, 'Slice the red onion as thinly as you can and steep it in the lemon juice for a few minutes.'),
  ('sa_butterbean', 3, 'Toss beans, peppers, onion and parsley with oil, salt and pepper.'),
  ('sa_butterbean', 4, 'Crumble feta over and add the spinach last.'),
  ('to_avo_egg', 1, 'Toast the bread properly — this dish is 40% toast.'),
  ('to_avo_egg', 2, 'Crush the avocado with lemon juice and a good pinch of salt, leaving it chunky.'),
  ('to_avo_egg', 3, 'Spread thickly, then top with halved boiled eggs.'),
  ('to_avo_egg', 4, 'Chilli flakes, black pepper, a final squeeze of lemon.'),
  ('to_beans_herb', 1, 'Drain the beans and warm them in a pan or microwave with grated garlic and a splash of water, 2 minutes.'),
  ('to_beans_herb', 2, 'Crush about a third of them against the side to thicken.'),
  ('to_beans_herb', 3, 'Stir in lemon juice, chopped parsley, salt and plenty of pepper.'),
  ('to_beans_herb', 4, 'Pile onto toast, finish with chilli flakes and oil.'),
  ('to_pb_banana', 1, 'Toast the bread.'),
  ('to_pb_banana', 2, 'Spread the peanut butter while it is hot so it melts slightly.'),
  ('to_pb_banana', 3, 'Layer sliced banana over the top.'),
  ('to_pb_banana', 4, 'Cinnamon and seeds to finish. Eat within the hour after a long run.'),
  ('bf_cherry_oats', 1, 'Stir oats, skyr, milk, chia and cinnamon together in a jar.'),
  ('bf_cherry_oats', 2, 'Drop the frozen cherries in on top — they thaw overnight and bleed into the oats.'),
  ('bf_cherry_oats', 3, 'Lid on, fridge, at least 6 hours.'),
  ('bf_cherry_oats', 4, 'Eat straight from the jar. Make three at a time on a Sunday.'),
  ('bf_skyr_bowl', 1, 'Take the berries out of the freezer the night before, or 20 seconds in the microwave.'),
  ('bf_skyr_bowl', 2, 'Spoon the skyr into a bowl and flatten the top.'),
  ('bf_skyr_bowl', 3, 'Pile berries, sliced banana, granola and seeds over.'),
  ('bf_skyr_bowl', 4, 'Eat immediately — granola goes soft fast.'),
  ('bf_pb_porridge', 1, 'Bring oats and milk to a simmer, stirring, 5–6 min until it thickens and the oats soften.'),
  ('bf_pb_porridge', 2, 'Off the heat, stir the peanut butter through until it streaks and melts.'),
  ('bf_pb_porridge', 3, 'Top with sliced banana, cinnamon and seeds.'),
  ('bf_pb_porridge', 4, 'Add a splash more milk if it stiffens while you find your socks.'),
  ('bf_eggs_avo', 1, 'Beat the eggs with salt. Put the toast on.'),
  ('bf_eggs_avo', 2, 'Melt butter in a cold pan, add the eggs, and stir constantly over low heat.'),
  ('bf_eggs_avo', 3, 'Pull the pan off while they still look slightly underdone — they carry on cooking.'),
  ('bf_eggs_avo', 4, 'Crush the avocado with lemon and salt onto the toast, spoon the eggs over, finish with chilli flakes.'),
  ('bf_recovery_smoothie', 1, 'Everything into the blender: cherries, banana, skyr, milk, oats, seeds.'),
  ('bf_recovery_smoothie', 2, 'Blitz 60 seconds until completely smooth — the oats need the full minute.'),
  ('bf_recovery_smoothie', 3, 'Loosen with more milk if it is too thick to drink quickly.'),
  ('bf_recovery_smoothie', 4, 'Drink within an hour of finishing a hard session.'),
  ('bf_miso_egg_rice', 1, 'Warm the rice with a splash of water, covered, 90 seconds.'),
  ('bf_miso_egg_rice', 2, 'Boil the eggs 6½ minutes for a jammy yolk, or fry them if you would rather.'),
  ('bf_miso_egg_rice', 3, 'Stir the miso through the hot rice with a little of the cooking water until it dissolves.'),
  ('bf_miso_egg_rice', 4, 'Top with the halved eggs, torn nori, spring onion, sesame and a drop of soy.'),
  ('bf_bagel_egg', 1, 'Halve and toast the bagel.'),
  ('bf_bagel_egg', 2, 'Spread cream cheese thickly on both halves.'),
  ('bf_bagel_egg', 3, 'Slice the boiled eggs and tomato, layer over the cream cheese, season hard.'),
  ('bf_bagel_egg', 4, 'Scatter spring onion, close, and eat. Wrap in foil if it is going out the door with you.'),
  ('bk_cherry_flapjack', 1, 'Heat oven to 180°C. Line a 20×30 cm tin.'),
  ('bk_cherry_flapjack', 2, 'Melt butter, sugar and syrup together in a pan until smooth — do not let it boil hard.'),
  ('bk_cherry_flapjack', 3, 'Stir in oats, cherries, seeds and cinnamon until every oat is coated.'),
  ('bk_cherry_flapjack', 4, 'Press firmly into the tin — firmly is what stops them crumbling — and bake 25 min until golden at the edges but still soft in the middle.'),
  ('bk_cherry_flapjack', 5, 'Cool completely in the tin before cutting into 12. They set as they cool.'),
  ('bk_banana_loaf', 1, 'Heat oven to 170°C. Line a 900 g loaf tin.'),
  ('bk_banana_loaf', 2, 'Mash the bananas to a purée, then beat in yogurt, eggs, sugar and oil.'),
  ('bk_banana_loaf', 3, 'Fold in flour, baking powder and bicarbonate until just combined — overmixing makes it tough.'),
  ('bk_banana_loaf', 4, 'Fold through the walnuts, pour into the tin, bake 50–55 min until a skewer comes out clean.'),
  ('bk_banana_loaf', 5, 'Cool in the tin 10 min, then on a rack. Slice and freeze what you will not eat in four days.'),
  ('bk_frittata_muffins', 1, 'Heat oven to 180°C. Oil a 12-hole muffin tin generously, or use cases.'),
  ('bk_frittata_muffins', 2, 'Wilt the spinach in a colander with boiling water from the kettle, then squeeze it bone dry — this step decides whether they are soggy.'),
  ('bk_frittata_muffins', 3, 'Beat the eggs with yogurt, salt and plenty of pepper.'),
  ('bk_frittata_muffins', 4, 'Divide spinach, chopped peppers, spring onion and crumbled feta between the holes, then pour the egg over to three-quarters full.'),
  ('bk_frittata_muffins', 5, 'Bake 20–22 min until puffed and set. They deflate as they cool — this is normal. Fridge four days.'),
  ('bk_cheese_carrot_muffins', 1, 'Heat oven to 190°C. Line a 12-hole muffin tin.'),
  ('bk_cheese_carrot_muffins', 2, 'Grate the carrots and most of the cheddar, keeping a handful of cheese back.'),
  ('bk_cheese_carrot_muffins', 3, 'Whisk eggs, yogurt and oil; stir in flour, baking powder, seeds, salt and pepper until only just combined.'),
  ('bk_cheese_carrot_muffins', 4, 'Fold through carrot and cheese, divide between cases, top with the reserved cheddar.'),
  ('bk_cheese_carrot_muffins', 5, 'Bake 22–25 min until risen and browned. Freeze half on day one.'),
  ('bk_energy_balls', 1, 'Pit the dates if needed and soak in hot water 5 min if they are dry. Drain well.'),
  ('bk_energy_balls', 2, 'Blitz dates, oats, peanut butter, cocoa and seeds to a coarse, sticky paste.'),
  ('bk_energy_balls', 3, 'If it will not hold together, add a teaspoon of water; if it is too wet, more oats.'),
  ('bk_energy_balls', 4, 'Roll into 16 balls, then roll in coconut.'),
  ('bk_energy_balls', 5, 'Chill 30 min to firm up. Fridge two weeks, freezer three months.'),
  ('bk_race_bars', 1, 'Line a small tin with baking paper — the mixture is aggressively sticky.'),
  ('bk_race_bars', 2, 'Warm the rice slightly so it presses together, then stir through maple syrup, peanut butter, sesame and salt.'),
  ('bk_race_bars', 3, 'Press hard into the tin, about 2 cm deep, and flatten with the back of a wet spoon.'),
  ('bk_race_bars', 4, 'Chill 1 hour, then cut into 10 bars and wrap each individually.'),
  ('bk_race_bars', 5, 'Test one on a long run before you trust them on a race.'),
  ('bk_soda_bread', 1, 'Heat oven to 200°C. Dust a baking tray with flour.'),
  ('bk_soda_bread', 2, 'Mix both flours, seeds, bicarbonate and salt in a big bowl.'),
  ('bk_soda_bread', 3, 'Stir the honey into the yogurt, then pour into the flour and bring together with a knife — barely mix it. Overworking makes it dense.'),
  ('bk_soda_bread', 4, 'Shape into a round on the tray, cut a deep cross in the top, and bake 40–45 min until it sounds hollow underneath.'),
  ('bk_soda_bread', 5, 'Cool on a rack at least 20 min before cutting. Best on days one and two, toast thereafter.')
insert into staples (ingredient_name, quantity_text, quantity_value, quantity_unit, category_code, sort_order) values
  ('porridge oats', '1 kg bag', 1, 'kg bag', 'N', 1),
  ('skyr or Greek yogurt', '2 large tubs', 2, 'large tubs', 'D', 2),
  ('frozen cherries', '1 bag', 1, 'bag', 'V', 3),
  ('frozen mixed berries', '1 bag', 1, 'bag', 'V', 4),
  ('eggs', '12', 12, null, 'D', 5),
  ('semi-skimmed or skimmed milk', '2 L', 2, 'L', 'D', 6),
  ('bananas', '1 bunch', 1, 'bunch', 'V', 7),
  ('chia or mixed seeds', '1 bag', 1, 'bag', 'S', 8),
  ('coffee', 'as needed', null, null, 'S', 9),
  ('chilli oil (crispy)', '1 jar', 1, 'jar', 'S', 10),
  ('neutral oil', '1 bottle', 1, 'bottle', 'S', 11),
  ('jasmine or basmati rice', '2 kg (works out cheaper)', 2, 'kg (works out cheaper)', 'N', 12)
insert into app_content (key, value) values
  ('sauna_rules', '{"hydration":"Weigh yourself before and after. Replace 150% of what you lost — 1.5 L per kg dropped — with electrolyte, not plain water. This is not general wellness advice; for you it is the difference between a recovery session and a gout trigger.","myth":"Ignore anything claiming sauna \"sweats out uric acid\". Measured urate in sweat is negligible to undetectable — your kidneys do that job, and sweating makes them worse at it, not better.","never":["During an active flare — heat on an inflamed joint makes it worse, and the fluid loss compounds it.","When you are already behind on fluid, or the morning after alcohol.","Straight after a long run without drinking first. Rehydrate, then heat.","Alone in the house if you are pushing a long session."],"heat_block":{"length_days":14,"ends_days_before_race":3,"sessions_per_week":5,"rest_days_of_week":[3,5]}}'::jsonb),
  ('pluralisation_exceptions', '["g","kg","ml","l","tbsp","tsp","cm","large","small","medium","to taste"]'::jsonb)
